new='''def find_opening_angle(s):
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '"':
            i += 1
            closed = False
            while i < n:
                c2 = s[i]
                if c2 == '\\\\':
                    i += 2
                    continue
                if c2 == '"':
                    closed = True
                    i += 1
                    break
                i += 1
            if not closed:
                raise UErr()
        elif c == '<':
            return i
        elif c == '>':
            raise UErr()
        else:
            i += 1
    return -1


def parse_address(s):
    if s == '':
        raise UErr()
    lt = find_opening_angle(s)
    if lt == -1:
        if any(c in ' \\t' for c in s):
            raise UErr()
        return parse_uri(s)
    gt = s.find('>', lt + 1)
    if gt < 0:
        raise UErr()
    if gt != len(s) - 1:
        raise UErr()
    inside = s[lt + 1:gt]
    if inside == '':
        raise UErr()
    if '<' in inside or '>' in inside:
        raise UErr()
    if any(c in ' \\t\\r\\n' for c in inside):
        raise UErr()
    validate_display_name(s[:lt])
    return parse_uri(inside)
'''

